1	locals {
2	  netpols = {
3	    "vector" = local.vector_netpol
4	  }
5	  vector_netpol = {
6	    endpointSelector = {
7	      matchLabels = {
8	        "app.kubernetes.io/name" = "vector"
9	      }
10	    }
11	    ingress = [
12	      {
13	        # OTLP from any cluster-internal sender (primarily otel-collector).
14	        # Port 8282 is the OPW-compatible Datadog Agent intake (datadog_agent source).
15	        fromEntities = ["cluster"]
16	        toPorts = [{
17	          ports = [
18	            { port = "4317" },
19	            { port = "4318" },
20	            { port = "8282" },
21	          ]
22	        }]
23	      },
24	      {
25	        # Vector self-metrics scrape (Prometheus operator, Datadog Agent, etc.).
26	        fromEntities = ["cluster"]
27	        toPorts = [{
28	          ports = [{ port = "8686" }]
29	        }]
30	      },
31	      {
32	        # kubelet health probes from the node.
33	        fromEntities = ["host"]
34	        toPorts = [{
35	          ports = [
36	            { port = "4317" },
37	            { port = "4318" },
38	            { port = "8686" },
39	          ]
40	        }]
41	      },
42	      {
43	        fromEntities = ["kube-apiserver"]
44	      }
45	    ]
46	    egress = [
47	      {
48	        # Datadog SaaS HTTPS for logs/traces/metrics sinks.
49	        toEntities = ["world"]
50	        toPorts = [{
51	          ports = [{ port = "443" }]
52	        }]
53	      },
54	      {
55	        toEntities = ["kube-apiserver"]
56	      },
57	      {
58	        # DNS resolution + service discovery (CoreDNS lives here).
59	        toEntities = ["cluster"]
60	      }
61	    ]
62	  }
63	}
