25	  apm_rules = file("${path.module}/processing-rules/${var.env}/apm.json")
26	  log_rules = file("${path.module}/processing-rules/${var.env}/rules.json")
27	  nowrds_instance = var.enable_nowrds_monitoring ? (<<-EON
28	    - dbm: true
29	      ssl: allow
30	      host: "%%env_NOWRDS_HOST%%"
31	      port: "%%env_NOWRDS_PORT%%"
32	      username: "%%env_NOWRDS_USERNAME%%"
33	      password: "%%env_NOWRDS_PASSWORD%%"
34	      collect_schemas:
35	        enabled: true
36	      database_autodiscovery:
37	        enabled: true
38	      tags:
39	        - "dbinstanceidentifier:%%env_NOWRDS_INSTANCE_NAME%%"
40	        - "env:%%env_DD_ENV%%"
41	  EON
42	  ) : null
43	}
